    --accent-color: #555;
    --bg-color: #f8f8f8;
    --text-color: #1a1a1a;
    --border-color: #e0e0e0;
    --focus-ring: 0 0 0 3px rgba(0, 0, 0, 0.2);
    --container-max-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--secondary-color);
}

.container {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: var(--secondary-color);
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header */
.site-header {
    padding: 1.5rem 0;
    border-bottom: 1px solid var(--border-color);
    background: var(--secondary-color);
    position: sticky;
    top: 0;
    z-index: 50;
}

.site-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo a {
    font-size: 1.5rem;
    font-weight: 700;
    text-decoration: none;
    color: var(--primary-color);
    text-transform: uppercase;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    text-decoration: none;
    color: var(--text-color);
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    position: relative;
    border-radius: 4px;
    transition: var(--transition);
}

.icon-button:hover {
    background: var(--bg-color);
}

.icon-button:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--primary-color);
    color: var(--secondary-color);
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.8rem 2rem;
    text-decoration: none;
    font-weight: 600;
    border-radius: 0;
    cursor: pointer;
    transition: var(--transition);
    border: 1px solid transparent;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background: #333;
}

.btn-outline {
    border: 1px solid var(--primary-color);
    background: transparent;
    color: var(--primary-color);
}

.btn-outline:hover {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-dark {
    background: var(--text-color);
    color: var(--secondary-color);
}

/* Hero */
.hero {
    background: #f0f0f0;
    padding: 8rem 0;
    text-align: center;
}

.hero-content h1 {
    font-size: 3.5rem;
    margin-bottom: 1.5rem;
    font-weight: 800;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: 2rem;
    color: var(--accent-color);
}

/* Section */
.section {
    padding: 5rem 0;
}

.section h2 {
    font-size: 2rem;
    margin-bottom: 3rem;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.product-card {
    border: 1px solid var(--border-color);
    padding: 1rem;
    transition: var(--transition);
}

.product-card:hover {
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.product-image img {
    width: 100%;
    height: auto;
    display: block;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    margin-bottom: 1.5rem;
}

.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
}

/* Deals */
.deals-banner {
    background: #111;
    color: #fff;
    padding: 4rem;
    text-align: center;
}

.deals-content h2 {
    color: #fff;
    margin-bottom: 1rem;
}

.deals-content p {
    margin-bottom: 2rem;
    font-size: 1.2rem;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card img {
    width: 100%;
    height: 400px;
    object-fit: cover;
    margin-bottom: 1.5rem;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.editorial-content p {
    color: var(--accent-color);
    margin-bottom: 1.5rem;
}

.editorial-content a {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    text-decoration: none;
    border-bottom: 2px solid var(--primary-color);
}

/* Footer */
.site-footer {
    background: #fdfdfd;
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .footer-logo {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    text-transform: uppercase;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.footer-nav h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.footer-nav ul {
    list-style: none;
}

.footer-nav li {
    margin-bottom: 0.75rem;
}

.footer-nav a {
    text-decoration: none;
    color: var(--accent-color);
    transition: var(--transition);
}

.footer-nav a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    font-size: 0.9rem;
    color: var(--accent-color);
}

/* Responsive */
@media (max-width: 768px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .nav-links {
        display: none; /* In a real app, I'd add a mobile menu */
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
