+document.addEventListener('DOMContentLoaded', () => {
+    const addToCartButtons = document.querySelectorAll('.add-to-cart');
+    const cartCountElement = document.querySelector('.cart-count');
+    const cartButton = document.getElementById('cart-button');
+    const liveRegion = document.getElementById('live-region');
+    
+    let cartCount = 0;
+
+    const updateCart = (productName) => {
+        cartCount++;
+        cartCountElement.textContent = cartCount;
+        
+        // Update accessible name for cart button
+        cartButton.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}`);
+        
+        // Notify screen readers
+        if (liveRegion) {
+            liveRegion.textContent = `${productName} added to cart. Total items: ${cartCount}`;
+        }
+    };
+
+    addToCartButtons.forEach(button => {
+        button.addEventListener('click', () => {
+            const productName = button.getAttribute('data-product');
+            updateCart(productName);
+        });
+    });
+
+    // Smooth scroll for anchor links
+    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
+        anchor.addEventListener('click', function (e) {
+            const href = this.getAttribute('href');
+            if (href !== '#') {
+                e.preventDefault();
+                const target = document.querySelector(href);
+                if (target) {
+                    target.scrollIntoView({
+                        behavior: 'smooth'
+                    });
+                    // Set focus to the target section for accessibility
+                    target.setAttribute('tabindex', '-1');
+                    target.focus({ preventScroll: true });
+                }
+            }
+        });
+    });
+});
+
')

