.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
}

/* Deals */
.deals-banner {
    background: #111;
    color: #fff;
    padding: 4rem;
    text-align: center;
}

.deals-content h2 {
    color: #fff;
    margin-bottom: 1rem;
}

.deals-content p {
    margin-bottom: 2rem;
    font-size: 1.2rem;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card img {
    width: 100%;
    height: 400px;
    object-fit: cover;
    margin-bottom: 1.5rem;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.editorial-content p {
    color: var(--accent-color);
    margin-bottom: 1.5rem;
}

.editorial-content a {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    text-decoration: none;
    border-bottom: 2px solid var(--primary-color);
}

/* Footer */
.site-footer {
    background: #fdfdfd;
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .footer-logo {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    text-transform: uppercase;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.footer-nav h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.footer-nav ul {
    list-style: none;
}

.footer-nav li {
    margin-bottom: 0.75rem;
}

.footer-nav a {
    text-decoration: none;
    color: var(--accent-color);
    transition: var(--transition);
}

.footer-nav a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    font-size: 0.9rem;
    color: var(--accent-color);
}

/* Responsive */
@media (max-width: 768px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .nav-links {
        display: none; /* In a real app, I'd add a mobile menu */
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
