.nav-links a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    position: relative;
    border-radius: 4px;
    transition: var(--transition);
}

.icon-button:hover {
    background: var(--bg-color);
}

.icon-button:focus-visible,
.btn:focus-visible,
.nav-links a:focus-visible,
.editorial-content a:focus-visible,
.footer-nav a:focus-visible {
    outline: 3px solid #005fcc;
    outline-offset: 4px;
    box-shadow: 0 0 0 6px rgba(0, 95, 204, 0.2);
}

.product-card:focus-within {
    border-color: var(--primary-color);
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

/* Typography improvement */
h1, h2, h3, .footer-logo, .logo a {
    font-family: "Playfair Display", serif; /* Fallback to serif */
}

/* Add a Google Font for better look if allowed, but since it's "plain HTML" I'll stick to system fonts but better stacks */
h1, h2, h3 {
    letter-spacing: -0.02em;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--primary-color);
    color: var(--secondary-color);
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.8rem 2rem;
    text-decoration: none;
    font-weight: 600;
    border-radius: 0;
    cursor: pointer;
    transition: var(--transition);
    border: 1px solid transparent;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background: #333;
}

.btn-outline {
    border: 1px solid var(--primary-color);
    background: transparent;
    color: var(--primary-color);
}

.btn-outline:hover {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-dark {
    background: var(--text-color);
    color: var(--secondary-color);
}

/* Hero */
.hero {
    background: #f0f0f0;
    padding: 8rem 0;
    text-align: center;
}

.hero-content h1 {
    font-size: 3.5rem;
    margin-bottom: 1.5rem;
    font-weight: 800;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: 2rem;
    color: var(--accent-color);
}

/* Section */
.section {
    padding: 5rem 0;
}

.section h2 {
    font-size: 2rem;
    margin-bottom: 3rem;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.product-card {
    border: 1px solid var(--border-color);
    padding: 1rem;
    transition: var(--transition);
}

.product-card:hover {
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.product-image img {
    width: 100%;
    height: auto;
    display: block;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    margin-bottom: 1.5rem;
}

.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
}

/* Deals */
.deals-banner {
    background: #111;
    color: #fff;
    padding: 4rem;
    text-align: center;
}

.deals-content h2 {
    color: #fff;
    margin-bottom: 1rem;
}

.deals-content p {
    margin-bottom: 2rem;
    font-size: 1.2rem;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card img {
    width: 100%;
    height: 400px;
    object-fit: cover;
    margin-bottom: 1.5rem;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.editorial-content p {
    color: var(--accent-color);
    margin-bottom: 1.5rem;
}

.editorial-content a {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    text-decoration: none;
    border-bottom: 2px solid var(--primary-color);
}

/* Footer */
.site-footer {
    background: #fdfdfd;
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .footer-logo {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    text-transform: uppercase;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.footer-nav h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.footer-nav ul {
    list-style: none;
}

.footer-nav li {
    margin-bottom: 0.75rem;
}

.footer-nav a {
    text-decoration: none;
    color: var(--accent-color);
    transition: var(--transition);
}

.footer-nav a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    font-size: 0.9rem;
    color: var(--accent-color);
}

/* Search Disclosure */
.search-disclosure {
    position: relative;
}

/* Hide search panel by default when JS is available */
[hidden] {
    display: none !important;
}

#search-panel {
    position: absolute;
    top: 100%;
    right: 0;
    background: var(--secondary-color);
    border: 1px solid var(--border-color);
    padding: 1rem;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
    width: 300px;
    margin-top: 0.5rem;
}

.search-form {
    display: flex;
    gap: 0.5rem;
}

.search-input {
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    flex-grow: 1;
}

/* Newsletter */
.newsletter {
    background: #fdfdfd;
}

.newsletter-card {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-card h2 {
    margin-bottom: 1rem;
}

.newsletter-card p {
    margin-bottom: 2rem;
    color: var(--accent-color);
}

.newsletter-form .form-group {
    display: flex;
    gap: 0;
}

.newsletter-form input {
    flex-grow: 1;
    padding: 1rem;
    border: 1px solid var(--border-color);
    border-right: none;
}

.newsletter-form button {
    padding: 1rem 2rem;
}

@media (max-width: 768px) {
    .newsletter-form .form-group {
        flex-direction: column;
    }
    .newsletter-form input {
        border-right: 1px solid var(--border-color);
        margin-bottom: 1rem;
    }
    .hero-content h1 {
        font-size: 2.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .nav-links {
        display: none; /* In a real app, I'd add a mobile menu */
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
